const LANDING = GARMENTS.find((g) => g.id === 'overshirt')

function useReducedMotion() {
  const [reduced, setReduced] = useState(
    () => typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
  )
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const on = () => setReduced(mq.matches)
    mq.addEventListener('change', on)
    return () => mq.removeEventListener('change', on)
  }, [])
  return reduced
}

/* ---------------------------------------------------------------------------
   The signature moment.

   A garment does one thing a photograph cannot show: it falls. So the chapter is
   ten real seconds of a coat being lifted, thrown, and landing on a body, cut to
   80 graded frames and scrubbed by the reader. The same scroll value that picks
   the frame also drives the rectangle the frame is drawn in — a small centred
   plate at the top, full bleed through the throw, and then, on the way out, the
   exact rectangle of the Wool Overshirt's image well in the shop below. The film
   does not cut to the shop; it becomes the first thing you can buy.
--------------------------------------------------------------------------- */

function FallChapter({ wellRef }) {
  const reduced = useReducedMotion()
  const trackRef = useRef(null)
  const stageRef = useRef(null)
  const canvasRef = useRef(null)
  const [ready, setReady] = useState(0)
  const framesRef = useRef(null)
  const stateRef = useRef({ p: 0, target: 0, w: 0, h: 0, dpr: 1 })

  // Load the real sequence. Desktop and mobile sets are authored separately.
  useEffect(() => {
    if (reduced) return
    const small = window.matchMedia('(max-width: 780px)').matches
    framesRef.current = loadSequence(manifest(small), (f) => setReady(f))
  }, [reduced])

  const paint = useCallback(() => {
    const canvas = canvasRef.current
    const stage = stageRef.current
    const frames = framesRef.current
    if (!canvas || !stage || !frames) return
    const st = stateRef.current
    const ctx = canvas.getContext('2d')
    const vw = st.w
    const vh = st.h
    const p = st.p

    // --- the one authored value, read three ways -------------------------
    const idx = Math.min(FRAME_COUNT - 1, Math.round(span(p, 0.05, 0.78) * (FRAME_COUNT - 1)))
    const open = ease(span(p, 0.0, 0.26)) // plate -> full bleed
    const out = ease(span(p, 0.75, 0.995)) // full bleed -> the shop card

    // entry plate: a tall lookbook plate, centred
    const ph = vh * 0.58
    const pw = Math.min(ph * (9 / 16), vw * 0.86)
    let x = mix((vw - pw) / 2, 0, open)
    let y = mix((vh - ph) / 2 - vh * 0.02, 0, open)
    let w = mix(pw, vw, open)
    let h = mix(ph, vh, open)

    // exit: hand the frame to the shop's image well, wherever it actually is
    if (out > 0) {
      const well = wellRef.current
      const r = well
        ? well.getBoundingClientRect()
        : { left: vw * 0.1, top: vh * 0.2, width: vw * 0.3, height: vh * 0.6 }
      x = mix(x, r.left, out)
      y = mix(y, r.top, out)
      w = mix(w, r.width, out)
      h = mix(h, r.height, out)
    }

    ctx.clearRect(0, 0, vw, vh)
    // the ink ground belongs to the chapter and leaves with it
    ctx.globalAlpha = 1 - ease(span(p, 0.74, 0.92))
    ctx.fillStyle = '#0b0b0a'
    ctx.fillRect(0, 0, vw, vh)
    ctx.globalAlpha = 1
    drawCover(ctx, frames[idx], x, y, w, h)

    // every cue rides the same value
    stage.style.setProperty('--c1', String(1 - span(p, 0.15, 0.25)))
    stage.style.setProperty('--c2', String(span(p, 0.27, 0.34) * (1 - span(p, 0.45, 0.53))))
    stage.style.setProperty('--c3', String(span(p, 0.55, 0.62) * (1 - span(p, 0.7, 0.76))))
    stage.style.setProperty('--open', String(open))
    stage.style.setProperty('--out', String(out))
    canvas.style.opacity = p > 0.995 ? '0' : '1'
  }, [wellRef])

  useEffect(() => {
    if (reduced) return
    const canvas = canvasRef.current
    let raf = 0
    let running = true

    const resize = () => {
      const st = stateRef.current
      st.dpr = Math.min(2, window.devicePixelRatio || 1)
      st.w = window.innerWidth
      st.h = window.innerHeight
      canvas.width = Math.round(st.w * st.dpr)
      canvas.height = Math.round(st.h * st.dpr)
      canvas.style.width = st.w + 'px'
      canvas.style.height = st.h + 'px'
      canvas.getContext('2d').setTransform(st.dpr, 0, 0, st.dpr, 0, 0)
    }

    const read = () => {
      const track = trackRef.current
      if (!track) return
      const r = track.getBoundingClientRect()
      // The track pins for its own height and then releases; the last viewport of
      // travel is the handoff, during which the shop scrolls up under the frame.
      stateRef.current.target = clamp(-r.top / r.height)
    }

    const tick = () => {
      if (!running) return
      const st = stateRef.current
      read()
      // Smoothing lives here, not on the document: native scroll is untouched.
      st.p += (st.target - st.p) * 0.16
      if (Math.abs(st.target - st.p) < 0.0002) st.p = st.target
      paint()
      raf = requestAnimationFrame(tick)
    }

    resize()
    window.addEventListener('resize', resize)
    raf = requestAnimationFrame(tick)
    return () => {
      running = false
      cancelAnimationFrame(raf)
      window.removeEventListener('resize', resize)
    }
  }, [reduced, paint])

  if (reduced) {
    return (
      <section className="chapter chapter--still" aria-labelledby="fall-title">
        <div className="still-plate">
          <img
            src="/media/fall-still.webp"
            alt="A long overcoat settled on the shoulders of a standing figure, photographed in low lamplight."
          />
        </div>
        <div className="still-words">
          <p className="eyebrow">Marlow &amp; Vale — Leeds</p>
          <h1 id="fall-title" className="display">How it falls</h1>
          <p className="line">A still can show you the colour. It cannot show you the weight.</p>
          <p className="note">Representative film of an overcoat being put on. Not a photograph of this garment.</p>
        </div>
      </section>
    )
  }

  return (
    <section className="chapter" ref={trackRef} aria-labelledby="fall-title">
      <canvas className="chapter-canvas" ref={canvasRef} aria-hidden="true" />
      <div className="chapter-stage" ref={stageRef}>
        <p className="eyebrow cue1">Marlow &amp; Vale — Leeds</p>
        <h1 id="fall-title" className="display cue1">
          How it<span>falls</span>
        </h1>
        <p className="line cue2">
          A still can show you the colour.
          <br />
          It cannot show you the weight.
        </p>
        <p className="line cue3">So we filmed the drop, and gave you the scroll.</p>
        <p className="note note--fixed">
          Representative film of an overcoat being put on. Not a photograph of this garment.
        </p>
        <p className="loading" data-done={ready >= 0.35 ? 'yes' : 'no'} aria-hidden={ready >= 0.35}>
          <span style={{ '--r': ready }} />
          {Math.round(ready * 100)}
        </p>
        <p className="scroll-hint cue1" aria-hidden="true">scroll</p>
      </div>
    </section>
  )
}

/* The landing. Phase one builds the first thing the film becomes: one real card,
   with its real sizes, in the shop's opening frame. */

function ShopEntry({ wellRef }) {
  const g = LANDING
  const [size, setSize] = useState(null)
  const [added, setAdded] = useState(0)
  return (
    <section className="shop" id="shop" aria-labelledby="shop-title">
      <header className="shop-head">
        <h2 id="shop-title" className="shop-title">The shop</h2>
        <p className="shop-sub">Nine things, one price all year.</p>
      </header>
      <article className="card">
        <div className="card-well" ref={wellRef}>
          <img
            src="/media/fall-still.webp"
            alt="A long overcoat settled on the shoulders of a standing figure, photographed in low lamplight."
          />
        </div>
        <div className="card-body">
          <p className="card-cat">{g.category}</p>
          <h3 className="card-name">{g.name}</h3>
          <p className="card-price">£{g.price}</p>
          <p className="card-detail">{g.detail}</p>
          <p className="card-fabric">{g.fabric}</p>
          <ul className="card-colours">
            {g.colours.map((c) => (
              <li key={c}>{c}</li>
            ))}
          </ul>
          <div className="sizes" role="group" aria-label={`Size, ${g.name}`}>
            {SIZES.map((s) => {
              const gone = g.sold.includes(s)
              return (
                <button
                  key={s}
                  type="button"
                  className="size"
                  disabled={gone}
                  aria-pressed={size === s}
                  onClick={() => setSize(s)}
                >
                  <span>{s}</span>
                  {gone ? <em>sold out</em> : null}
                </button>
              )
            })}
          </div>
          <button type="button" className="add" disabled={!size} onClick={() => setAdded((n) => n + 1)}>
            {size ? `Add size ${size} — £${g.price}` : 'Choose a size'}
          </button>
          <p className="card-note">
            Image is representative film, not a photograph of this garment.
            {added > 0 ? ` · ${added} in the bag` : ''}
          </p>
        </div>
      </article>
    </section>
  )
}

export default function App() {
  const wellRef = useRef(null)
  return (
    <>
      <a className="skip" href="#shop">Skip to the shop</a>
      <main>
        <FallChapter wellRef={wellRef} />
        <ShopEntry wellRef={wellRef} />
      </main>
    </>
  )
}

/* Marlow & Vale — phase one: the chapter where the coat falls, and its landing. */

:root {
  --ink: #0b0b0a;
  --ink-2: #16150f;
  --bone: #ece7dc;
  --bone-2: #dcd5c5;
  --olive: #5f6349;
  --clay: #8a4b2f;
  --rule: rgb(11 11 10 / 0.18);

  --display: 'Fraunces', 'Iowan Old Style', Georgia, serif;
  --sans: 'IBM Plex Sans', system-ui, -apple-system, sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;

  --step: clamp(0.85rem, 0.78rem + 0.3vw, 0.98rem);
  --gutter: clamp(1.25rem, 4vw, 4.5rem);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--ink);
  color: var(--bone);
  font-family: var(--sans);
  font-size: var(--step);
  line-height: 1.5;
  overflow-x: hidden;
}

img { display: block; max-width: 100%; }

::selection { background: var(--clay); color: var(--bone); }

.skip {
  position: fixed;
  top: 0.6rem;
  left: 0.6rem;
  z-index: 50;
  padding: 0.6rem 1rem;
  background: var(--bone);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  transform: translateY(-160%);
  transition: transform 160ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.skip:focus-visible { transform: none; outline: 2px solid var(--clay); outline-offset: 2px; }

:where(button, a):focus-visible {
  outline: 2px solid var(--clay);
  outline-offset: 3px;
}

/* ---------------------------------------------------------------- chapter */

.chapter {
  position: relative;
  height: 400vh;
}

.chapter-canvas {
  position: fixed;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  pointer-events: none;
  transition: opacity 180ms linear;
}

.chapter-stage {
  position: sticky;
  top: 0;
  z-index: 2;
  height: 100svh;
  padding: clamp(1.1rem, 3.5vh, 2.4rem) var(--gutter);
  pointer-events: none;
  display: grid;
  grid-template-rows: auto 1fr auto;
  mix-blend-mode: normal;
}

.eyebrow {
  margin: 0;
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: rgb(236 231 220 / 0.72);
}

/* the entry title: set large, straddling the plate, so the plate opens through it */
.display {
  grid-row: 2;
  align-self: center;
  justify-self: start;
  margin: 0;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(3.2rem, 13vw, 11rem);
  line-height: 0.84;
  letter-spacing: -0.03em;
  text-transform: lowercase;
  color: var(--bone);
  mix-blend-mode: difference;
  transform: translateY(calc(var(--open, 0) * -4vh));
}
.display span { display: block; padding-left: 1.6em; font-style: italic; }

.line {
  grid-row: 2;
  align-self: center;
  justify-self: center;
  max-width: 22ch;
  margin: 0;
  text-align: center;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(1.5rem, 3.4vw, 3rem);
  line-height: 1.18;
  letter-spacing: -0.01em;
  text-wrap: balance;
  text-shadow: 0 0.4rem 3rem rgb(11 11 10 / 0.85);
}

.cue1 { opacity: var(--c1, 1); }
.cue2 { opacity: var(--c2, 0); transform: translateY(calc((1 - var(--c2, 0)) * 1.2rem)); }
.cue3 { opacity: var(--c3, 0); transform: translateY(calc((1 - var(--c3, 0)) * 1.2rem)); }

.note {
  margin: 0;
  font-family: var(--mono);
  font-size: 0.64rem;
  letter-spacing: 0.06em;
  color: rgb(236 231 220 / 0.5);
  max-width: 34ch;
}
.note--fixed {
  grid-row: 3;
  align-self: end;
  justify-self: start;
  opacity: calc(0.35 + 0.65 * (1 - var(--out, 0)));
}

.scroll-hint {
  grid-row: 3;
  align-self: end;
  justify-self: end;
  margin: 0;
  font-family: var(--mono);
  font-size: 0.64rem;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: rgb(236 231 220 / 0.55);
}
.scroll-hint::after {
  content: '';
  display: block;
  height: 2.6rem;
  width: 1px;
  margin: 0.6rem auto 0;
  background: linear-gradient(var(--bone), transparent);
  animation: drop 2.4s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  transform-origin: top;
}
@keyframes drop {
  0% { transform: scaleY(0); opacity: 0; }
  35% { transform: scaleY(1); opacity: 1; }
  100% { transform: scaleY(1) translateY(2.6rem); opacity: 0; }
}

.loading {
  grid-row: 3;
  align-self: end;
  justify-self: center;
  margin: 0;
  font-family: var(--mono);
  font-size: 0.64rem;
  letter-spacing: 0.2em;
  color: rgb(236 231 220 / 0.6);
  display: flex;
  align-items: center;
  gap: 0.6rem;
  transition: opacity 400ms ease;
}
.loading[data-done='yes'] { opacity: 0; }
.loading span {
  display: block;
  width: 8rem;
  height: 1px;
  background: rgb(236 231 220 / 0.25);
  position: relative;
}
.loading span::after {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--r, 0) * 100%);
  background: var(--bone);
}

/* reduced motion: one authored still, chosen — not the sequence switched off */
.chapter--still {
  min-height: 100svh;
  display: grid;
  gap: clamp(1.5rem, 4vw, 3rem);
  grid-template-columns: 1fr;
  align-content: center;
  padding: clamp(2rem, 8vh, 6rem) var(--gutter);
}
.still-plate img {
  width: min(100%, 34rem);
  margin-inline: auto;
  aspect-ratio: 9 / 16;
  object-fit: cover;
}
.still-words { display: grid; gap: 1rem; max-width: 34rem; margin-inline: auto; }
.chapter--still .display {
  mix-blend-mode: normal;
  transform: none;
  font-size: clamp(2.6rem, 8vw, 5rem);
}
.chapter--still .line {
  justify-self: start;
  text-align: left;
  font-size: clamp(1.1rem, 2.4vw, 1.6rem);
  text-shadow: none;
  max-width: 30ch;
}
@media (min-width: 900px) {
  .chapter--still { grid-template-columns: minmax(0, 26rem) minmax(0, 1fr); align-items: center; }
  .still-words { margin-inline: 0; }
}

/* ------------------------------------------------------------------- shop */

.shop {
  position: relative;
  z-index: 3;
  background: var(--bone);
  color: var(--ink);
  min-height: 100svh;
  padding: clamp(1.4rem, 4vh, 2.6rem) var(--gutter) clamp(4rem, 12vh, 8rem);
  display: grid;
  grid-template-rows: auto 1fr;
  gap: clamp(1.2rem, 3vh, 2rem);
}

.shop-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  padding-bottom: 0.9rem;
  border-bottom: 1px solid var(--rule);
}
.shop-title {
  margin: 0;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  letter-spacing: -0.02em;
}
.shop-sub {
  margin: 0;
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgb(11 11 10 / 0.6);
}

.card {
  display: grid;
  gap: clamp(1.2rem, 3vw, 3rem);
  align-items: stretch;
}
@media (min-width: 860px) {
  .card { grid-template-columns: minmax(0, 27rem) minmax(0, 1fr); }
}

.card-well {
  position: relative;
  aspect-ratio: 9 / 16;
  max-height: 76vh;
  background: var(--ink);
  overflow: hidden;
}
.card-well img { width: 100%; height: 100%; object-fit: cover; }

.card-body {
  display: grid;
  align-content: start;
  gap: 0.55rem;
  max-width: 40rem;
  padding-top: clamp(0.5rem, 4vh, 3rem);
}
.card-cat {
  margin: 0;
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--olive);
}
.card-name {
  margin: 0;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(2.1rem, 5vw, 3.4rem);
  line-height: 1;
  letter-spacing: -0.025em;
}
.card-price {
  margin: 0 0 0.4rem;
  font-family: var(--mono);
  font-size: 1rem;
  letter-spacing: 0.02em;
}
.card-detail {
  margin: 0;
  font-size: clamp(1rem, 1.4vw, 1.15rem);
  line-height: 1.45;
  max-width: 34ch;
}
.card-fabric {
  margin: 0.4rem 0 0;
  font-family: var(--mono);
  font-size: 0.72rem;
  line-height: 1.6;
  color: rgb(11 11 10 / 0.66);
  border-top: 1px solid var(--rule);
  padding-top: 0.7rem;
  max-width: 40ch;
}
.card-colours {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin: 0.2rem 0 0.6rem;
  padding: 0;
  list-style: none;
}
.card-colours li {
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.06em;
  padding: 0.25rem 0.55rem;
  border: 1px solid var(--rule);
  border-radius: 999px;
  color: rgb(11 11 10 / 0.7);
}

.sizes { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-top: 0.3rem; }
.size {
  position: relative;
  min-width: 3.4rem;
  min-height: 3rem;
  padding: 0.55rem 0.7rem 0.5rem;
  background: transparent;
  border: 1px solid var(--ink);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 0.82rem;
  letter-spacing: 0.06em;
  cursor: pointer;
  display: grid;
  gap: 0.1rem;
  justify-items: center;
  transition: background 140ms ease, color 140ms ease, transform 140ms ease;
}
.size em {
  font-style: normal;
  font-size: 0.52rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.75;
}
.size:hover:not(:disabled) { background: rgb(11 11 10 / 0.07); }
.size:active:not(:disabled) { transform: translateY(1px); }
.size[aria-pressed='true'] { background: var(--ink); color: var(--bone); }
.size:disabled {
  cursor: not-allowed;
  color: rgb(11 11 10 / 0.34);
  border-color: rgb(11 11 10 / 0.16);
  background: repeating-linear-gradient(
    -45deg,
    transparent 0 5px,
    rgb(11 11 10 / 0.06) 5px 6px
  );
}

.add {
  margin-top: 0.8rem;
  justify-self: start;
  min-height: 3.1rem;
  padding: 0.85rem 1.6rem;
  background: var(--ink);
  color: var(--bone);
  border: 1px solid var(--ink);
  font-family: var(--mono);
  font-size: 0.76rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 140ms ease, color 140ms ease, transform 140ms ease;
}
.add:hover:not(:disabled) { background: var(--clay); border-color: var(--clay); }
.add:active:not(:disabled) { transform: translateY(1px); }
.add:disabled { background: transparent; color: rgb(11 11 10 / 0.4); border-color: var(--rule); cursor: not-allowed; }

.card-note {
  margin: 0.6rem 0 0;
  font-family: var(--mono);
  font-size: 0.62rem;
  letter-spacing: 0.05em;
  color: rgb(11 11 10 / 0.5);
  max-width: 44ch;
}

@media (max-width: 859px) {
  .card-well { max-height: 62vh; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

