import { useEffect } from 'react'

// The interaction baseline's entrance half. One observer for the whole route.
// Thresholds are measured against the TOP of the viewport so a reveal always
// finishes while its region is still on screen.
export function useReveal(reduced) {
  useEffect(() => {
    const nodes = Array.from(document.querySelectorAll('[data-reveal]'))
    if (reduced) {
      nodes.forEach((n) => n.classList.add('is-in'))
      return
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add('is-in')
            io.unobserve(e.target)
          }
        })
      },
      { rootMargin: '0px 0px -12% 0px', threshold: 0.01 },
    )
    nodes.forEach((n) => io.observe(n))
    return () => io.disconnect()
  }, [reduced])
}

// Marlow & Vale. Content constants are the product requirement and are preserved exactly;
// the page around them is authored.
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { FRAME_COUNT, clamp, drawCover, ease, loadSequence, manifest, mix, span } from './fall.js'
import { useReveal } from './useReveal.js'

const SIZES = ['XS', 'S', 'M', 'L', 'XL']

// A normal clothing shop: nine garments across three categories, sized, some sizes gone.
