/* ---------------------------------------------------------------------- bag */

function Bag({ bag, remove, open, setOpen }) {
  const total = bag.reduce((sum, line) => sum + line.price, 0)
  const postage = total === 0 || total >= 100 ? 0 : 4.95
  const drawer = useRef(null)

  useEffect(() => {
    if (!open) return
    const onKey = (e) => e.key === 'Escape' && setOpen(false)
    window.addEventListener('keydown', onKey)
    const first = drawer.current?.querySelector('button')
    first?.focus()
    return () => window.removeEventListener('keydown', onKey)
  }, [open, setOpen])

  return (
    <>
      <button
        type="button"
        className="bag-tab"
        aria-expanded={open}
        aria-controls="bag-drawer"
        onClick={() => setOpen(!open)}
      >
        Bag <b>{bag.length}</b>
      </button>

      <div
        className={`bag${open ? ' is-open' : ''}`}
        id="bag-drawer"
        ref={drawer}
        role="dialog"
        aria-label="Your bag"
        aria-hidden={!open}
      >
        <div className="bag-head">
          <h2>Your bag</h2>
          <button type="button" className="x" onClick={() => setOpen(false)} aria-label="Close bag">
            ✕
          </button>
        </div>

        {bag.length === 0 ? (
          <p className="bag-empty">Your bag is empty.</p>
        ) : (
          <>
            <ul className="bag-lines">
              {bag.map((line, i) => (
                <li key={`${line.id}-${i}`}>
                  <span className="bag-name">{line.name}</span>
                  <span className="bag-size">size {line.size}</span>
                  <span className="bag-price">£{line.price}</span>
                  <button type="button" className="link" onClick={() => remove(i)}>
                    Remove
                  </button>
                </li>
              ))}
            </ul>
            <div className="bag-sum">
              <p>
                <span>Subtotal</span>
                <b>{money(total)}</b>
              </p>
              <p>
                <span>Delivery</span>
                <b>{postage === 0 ? 'Free' : money(postage)}</b>
              </p>
              {postage > 0 ? (
                <p className="bag-nudge">
                  {money(100 - total)} more for free delivery.
                  <span className="nudge-track" aria-hidden="true">
                    <span style={{ '--w': `${Math.min(100, (total / 100) * 100)}%` }} />
                  </span>
                </p>
              ) : (
                <p className="bag-nudge">Free delivery on orders over £100.</p>
              )}
              <p className="bag-total">
                <span>Total</span>
                <b>{money(total + postage)}</b>
              </p>
              <button type="button" className="add">Checkout</button>
            </div>
          </>
        )}
      </div>
      <button
        type="button"
        className={`scrim${open ? ' is-open' : ''}`}
        tabIndex={open ? 0 : -1}
        aria-label="Close bag"
        onClick={() => setOpen(false)}
      />
    </>
  )
}

/* --------------------------------------------------------------------- head */

function TopBar({ past, onBag, count }) {
  return (
    <header className={`topbar${past ? ' is-on' : ''}`}>
      <a className="wordmark" href="#top">Marlow &amp; Vale</a>
      <nav className="nav">
        <a href="#grid">Shop</a>
        <a href="#sizing">Size</a>
        <a href="#care">Care</a>
        <a href="#delivery">Delivery</a>
      </nav>
      <button type="button" className="nav-bag" onClick={onBag}>
        Bag <b>{count}</b>
      </button>
    </header>
  )
}

export default function App() {
  const reduced = useReducedMotion()
  const wellRef = useRef(null)
  const [chosen, setChosen] = useState({})
  const [bag, setBag] = useState([])
  const [open, setOpen] = useState(false)
  const [past, setPast] = useState(false)

  useReveal(reduced)

  useEffect(() => {
    const onScroll = () => setPast(window.scrollY > window.innerHeight * (reduced ? 0.6 : 3.4))
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [reduced])

  const choose = (id, size) => setChosen((c) => ({ ...c, [id]: size }))

  const add = (garment) => {
    const size = chosen[garment.id]
    if (!size || garment.sold.includes(size)) return
    setBag((b) => [...b, { id: garment.id, name: garment.name, size, price: garment.price }])
    setOpen(true)
  }

  const remove = (i) => setBag((b) => b.filter((_, j) => j !== i))

  const count = useMemo(() => bag.length, [bag])

  return (
    <>
      <a className="skip" href="#shop">Skip to the shop</a>
      <span id="top" />
      <TopBar past={past} count={count} onBag={() => setOpen(true)} />
      <main>
        <FallChapter wellRef={wellRef} />
        <FirstLook wellRef={wellRef} chosen={chosen} choose={choose} add={add} />
        <Shop chosen={chosen} choose={choose} add={add} />
        <RailBand reduced={reduced} />
        <Sizing />
        <Care />
        <Ship />
        <Reviews />
      </main>
      <footer className="foot">
        <p className="wordmark wordmark--foot">Marlow &amp; Vale</p>
        <p className="micro">
          Eleven people, one shop in Leeds. Never any sales. All film on this page is
          representative stock footage, graded by us — none of it photographs our garments.
        </p>
      </footer>
      <Bag bag={bag} remove={remove} open={open} setOpen={setOpen} />
    </>
  )
}

/* Marlow & Vale.
   Ink is the film. Bone is the shop. The route alternates between them, and the
   one thing that crosses every boundary is the footage: it opens the page, lands
   in the first card, travels sideways behind the facts, and lies under the care
   notes as cloth. */

:root {
  --ink: #0b0b0a;
  --ink-2: #14140f;
  --bone: #ece7dc;
  --bone-2: #e2dccd;
  --olive: #5f6349;
  --clay: #8a4b2f;
  --rule: rgb(11 11 10 / 0.18);
  --rule-bone: rgb(236 231 220 / 0.18);

  --display: 'Fraunces', 'Iowan Old Style', Georgia, serif;
  --sans: 'IBM Plex Sans', system-ui, -apple-system, sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;

  --step: clamp(0.9rem, 0.82rem + 0.3vw, 1rem);
  --gutter: clamp(1.25rem, 4vw, 4.5rem);
  --ease: cubic-bezier(0.2, 0.7, 0.2, 1);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; scroll-padding-top: 5rem; }

body {
  margin: 0;
  background: var(--ink);
  color: var(--bone);
  font-family: var(--sans);
  font-size: var(--step);
  line-height: 1.5;
  overflow-x: hidden;
}

img { display: block; max-width: 100%; }

::selection { background: var(--clay); color: var(--bone); }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip {
  position: fixed;
  top: 0.6rem;
  left: 0.6rem;
  z-index: 60;
  padding: 0.6rem 1rem;
  background: var(--bone);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  transform: translateY(-160%);
  transition: transform 160ms var(--ease);
}
.skip:focus-visible { transform: none; outline: 2px solid var(--clay); outline-offset: 2px; }

:where(button, a):focus-visible {
  outline: 2px solid var(--clay);
  outline-offset: 3px;
}

/* --- the entrance half of the interaction baseline ------------------------ */

[data-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 620ms var(--ease), transform 620ms var(--ease);
  transition-delay: calc(var(--i, 0) * 80ms);
}
[data-reveal].is-in { opacity: 1; transform: none; }

/* ---------------------------------------------------------------- typography */

.h2 {
  margin: 0;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(1.9rem, 4.2vw, 3.3rem);
  line-height: 1.02;
  letter-spacing: -0.025em;
  max-width: 16ch;
}
.h2--bone { color: var(--bone); }

.eyebrow {
  margin: 0;
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: rgb(236 231 220 / 0.72);
}
.eyebrow--ink { color: var(--olive); }

.spec {
  margin: 0.4rem 0 0;
  font-family: var(--mono);
  font-size: 0.72rem;
  line-height: 1.6;
  color: rgb(11 11 10 / 0.66);
  border-top: 1px solid var(--rule);
  padding-top: 0.7rem;
  max-width: 40ch;
}

.micro {
  margin: 0;
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.05em;
  line-height: 1.6;
  color: rgb(11 11 10 / 0.55);
  max-width: 46ch;
}

.note {
  margin: 0;
  font-family: var(--mono);
  font-size: 0.64rem;
  letter-spacing: 0.06em;
  color: rgb(236 231 220 / 0.5);
  max-width: 34ch;
}

/* ------------------------------------------------------------------- topbar */

.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: clamp(0.75rem, 3vw, 2rem);
  padding: 0.75rem var(--gutter);
  background: rgb(236 231 220 / 0.92);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--rule);
  transform: translateY(-101%);
  transition: transform 420ms var(--ease);
}
.topbar.is-on { transform: none; }

.wordmark {
  font-family: var(--display);
  font-size: 1.05rem;
  letter-spacing: -0.01em;
  color: var(--ink);
  text-decoration: none;
  margin-right: auto;
}

.nav { display: none; gap: 1.4rem; }
.nav a {
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgb(11 11 10 / 0.62);
  text-decoration: none;
  padding-bottom: 2px;
  border-bottom: 1px solid transparent;
  transition: color 140ms var(--ease), border-color 140ms var(--ease);
}
.nav a:hover { color: var(--ink); border-bottom-color: var(--clay); }
@media (min-width: 820px) { .nav { display: flex; } }

.nav-bag {
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  background: transparent;
  border: 1px solid var(--ink);
  color: var(--ink);
  padding: 0.5rem 0.85rem;
  min-height: 2.4rem;
  cursor: pointer;
  transition: background 140ms var(--ease), color 140ms var(--ease), transform 140ms var(--ease);
}
.nav-bag b { font-weight: 500; }
.nav-bag:hover { background: var(--ink); color: var(--bone); }
.nav-bag:active { transform: translateY(1px); }

/* ---------------------------------------------------------------- chapter */

.chapter {
  position: relative;
  height: 400vh;
}

/* the film flies over the shop on its way into the card, then hands over */
.chapter-canvas {
  position: fixed;
  inset: 0;
  z-index: 4;
  width: 100%;
  height: 100%;
  pointer-events: none;
  transition: opacity 180ms linear;
}

.chapter-stage {
  position: sticky;
  top: 0;
  z-index: 5;
  height: 100svh;
  padding: clamp(1.1rem, 3.5vh, 2.4rem) var(--gutter);
  pointer-events: none;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto 1fr auto;
}

.chapter-stage > * { grid-column: 1; }

/* the entry title: set large, straddling the plate, so the plate opens through it */
.display {
  grid-row: 2;
  align-self: center;
  justify-self: start;
  margin: 0;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(3.2rem, 13vw, 11rem);
  line-height: 0.84;
  letter-spacing: -0.03em;
  text-transform: lowercase;
  color: var(--bone);
  mix-blend-mode: difference;
  transform: translateY(calc(var(--open, 0) * -4vh));
}
.display span { display: block; padding-left: 1.6em; font-style: italic; }

.line {
  grid-row: 2;
  align-self: center;
  justify-self: center;
  max-width: 22ch;
  margin: 0;
  text-align: center;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(1.5rem, 3.4vw, 3rem);
  line-height: 1.18;
  letter-spacing: -0.01em;
  text-wrap: balance;
  text-shadow: 0 0.4rem 3rem rgb(11 11 10 / 0.85);
}

.cue1 { opacity: var(--c1, 1); }
.cue2 { opacity: var(--c2, 0); transform: translateY(calc((1 - var(--c2, 0)) * 1.2rem)); }
.cue3 {
  opacity: var(--c3, 0);
  transform: translateY(calc((1 - var(--c3, 0)) * 1.2rem));
  justify-self: end;
  text-align: right;
  max-width: 16ch;
}

.note--fixed {
  grid-row: 3;
  align-self: end;
  justify-self: start;
  opacity: calc(1 - var(--out, 0));
}

.scroll-hint {
  grid-row: 3;
  align-self: end;
  justify-self: end;
  margin: 0;
  font-family: var(--mono);
  font-size: 0.64rem;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: rgb(236 231 220 / 0.55);
}
.scroll-hint::after {
  content: '';
  display: block;
  height: 2.6rem;
  width: 1px;
  margin: 0.6rem auto 0;
  background: linear-gradient(var(--bone), transparent);
  animation: drop 2.4s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  transform-origin: top;
}
@keyframes drop {
  0% { transform: scaleY(0); opacity: 0; }
  35% { transform: scaleY(1); opacity: 1; }
  100% { transform: scaleY(1) translateY(2.6rem); opacity: 0; }
}

.loading {
  grid-row: 3;
  align-self: end;
  justify-self: center;
  margin: 0;
  font-family: var(--mono);
  font-size: 0.64rem;
  letter-spacing: 0.2em;
  color: rgb(236 231 220 / 0.6);
  display: flex;
  align-items: center;
  gap: 0.6rem;
  transition: opacity 400ms ease;
}
.loading[data-done='yes'] { opacity: 0; }
.loading span {
  display: block;
  width: 8rem;
  height: 1px;
  background: rgb(236 231 220 / 0.25);
  position: relative;
}
.loading span::after {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--r, 0) * 100%);
  background: var(--bone);
}

/* reduced motion: one authored still, chosen — not the sequence switched off */
.chapter--still {
  height: auto;
  min-height: 100svh;
  display: grid;
  gap: clamp(1.5rem, 4vw, 3rem);
  grid-template-columns: 1fr;
  align-content: center;
  padding: clamp(2rem, 8vh, 6rem) var(--gutter);
}
.still-plate img {
  width: min(100%, 34rem);
  margin-inline: auto;
  aspect-ratio: 9 / 16;
  object-fit: cover;
}
.still-words { display: grid; gap: 1rem; max-width: 34rem; margin-inline: auto; }
.chapter--still :where(.display, .line, .eyebrow, .note) {
  grid-row: auto;
  grid-column: auto;
  justify-self: start;
  align-self: auto;
}
.chapter--still .display {
  mix-blend-mode: normal;
  transform: none;
  font-size: clamp(2.6rem, 8vw, 5rem);
}
.chapter--still .line {
  justify-self: start;
  text-align: left;
  font-size: clamp(1.1rem, 2.4vw, 1.6rem);
  text-shadow: none;
  max-width: 30ch;
}
@media (min-width: 900px) {
  .chapter--still { grid-template-columns: minmax(0, 26rem) minmax(0, 1fr); align-items: center; }
  .still-words { margin-inline: 0; }
}

/* -------------------------------------------------------------- first look */

.look {
  position: relative;
  z-index: 3;
  background: var(--bone);
  color: var(--ink);
  min-height: 100svh;
  padding: clamp(1.4rem, 4vh, 2.6rem) var(--gutter) clamp(3rem, 8vh, 6rem);
  display: grid;
  gap: clamp(1.4rem, 3vw, 3.5rem);
  align-content: start;
}
@media (min-width: 860px) {
  .look { grid-template-columns: minmax(0, 27rem) minmax(0, 1fr); align-items: start; }
}

.look-plate { display: grid; gap: 0.55rem; }

.card-well {
  position: relative;
  aspect-ratio: 9 / 16;
  max-height: 78vh;
  background: var(--ink);
  overflow: hidden;
}
.card-well img { width: 100%; height: 100%; object-fit: cover; }

.note--under { color: rgb(11 11 10 / 0.5); }

.look-body {
  display: grid;
  align-content: start;
  gap: 0.55rem;
  max-width: 42rem;
  padding-top: clamp(0.5rem, 5vh, 3.5rem);
}
.look-name {
  margin: 0.2rem 0 0;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(2.2rem, 5.4vw, 3.8rem);
  line-height: 1;
  letter-spacing: -0.025em;
}
.look-price {
  margin: 0 0 0.4rem;
  font-family: var(--mono);
  font-size: 1rem;
}
.look-detail {
  margin: 0;
  font-size: clamp(1.02rem, 1.4vw, 1.2rem);
  line-height: 1.45;
  max-width: 34ch;
}

.chips { display: flex; flex-wrap: wrap; gap: 0.4rem; margin: 0.5rem 0 0.4rem; padding: 0; list-style: none; }
.chips li {
  display: flex;
  align-items: center;
  gap: 0.42rem;
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.05em;
  padding: 0.28rem 0.6rem 0.28rem 0.32rem;
  border: 1px solid var(--rule);
  border-radius: 999px;
  color: rgb(11 11 10 / 0.72);
}
.chips i { width: 0.85rem; height: 0.85rem; border-radius: 50%; box-shadow: inset 0 0 0 1px rgb(11 11 10 / 0.2); }

/* ----------------------------------------------------------- size controls */

.sizes { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-top: 0.5rem; }
.size {
  position: relative;
  min-width: 3.4rem;
  min-height: 3rem;
  padding: 0.5rem 0.7rem;
  background: transparent;
  border: 1px solid var(--ink);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 0.82rem;
  letter-spacing: 0.06em;
  cursor: pointer;
  display: grid;
  gap: 0.1rem;
  align-content: center;
  justify-items: center;
  transition: background 140ms var(--ease), color 140ms var(--ease), transform 140ms var(--ease);
}
.size em {
  font-style: normal;
  font-size: 0.5rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.75;
}
.size:hover:not(:disabled) { background: rgb(11 11 10 / 0.07); }
.size:active:not(:disabled) { transform: translateY(1px); }
.size[aria-pressed='true'] { background: var(--ink); color: var(--bone); }
.size:disabled {
  cursor: not-allowed;
  color: rgb(11 11 10 / 0.34);
  border-color: rgb(11 11 10 / 0.16);
  background: repeating-linear-gradient(-45deg, transparent 0 5px, rgb(11 11 10 / 0.06) 5px 6px);
}

.add {
  margin-top: 0.8rem;
  justify-self: start;
  min-height: 3.1rem;
  padding: 0.85rem 1.6rem;
  background: var(--ink);
  color: var(--bone);
  border: 1px solid var(--ink);
  font-family: var(--mono);
  font-size: 0.76rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 140ms var(--ease), color 140ms var(--ease), transform 140ms var(--ease);
}
.add--sm { min-height: 2.8rem; padding: 0.7rem 1.1rem; font-size: 0.7rem; margin-top: 0.6rem; }
.add:hover:not(:disabled) { background: var(--clay); border-color: var(--clay); }
.add:active:not(:disabled) { transform: translateY(1px); }
.add:disabled { background: transparent; color: rgb(11 11 10 / 0.4); border-color: var(--rule); cursor: not-allowed; }

/* --------------------------------------------------------------------- shop */

.shop {
  position: relative;
  z-index: 3;
  background: var(--bone);
  color: var(--ink);
  padding: clamp(2rem, 7vh, 5rem) var(--gutter) clamp(3rem, 9vh, 7rem);
  border-top: 1px solid var(--rule);
}

.shop-head {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2rem 2rem;
  align-items: end;
  justify-content: space-between;
  padding-bottom: 1rem;
}
.shop-head > div { display: grid; gap: 0.6rem; }

.filter { display: flex; flex-wrap: wrap; gap: 0.45rem; }
.chip {
  background: transparent;
  border: 1px solid var(--rule);
  border-radius: 999px;
  color: rgb(11 11 10 / 0.72);
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  padding: 0.55rem 0.95rem;
  min-height: 2.6rem;
  cursor: pointer;
  transition: background 140ms var(--ease), color 140ms var(--ease),
    border-color 140ms var(--ease), transform 140ms var(--ease);
}
.chip b { font-weight: 400; opacity: 0.55; margin-left: 0.3rem; }
.chip:hover { border-color: var(--ink); color: var(--ink); }
.chip:active { transform: translateY(1px); }
.chip[aria-pressed='true'] { background: var(--ink); border-color: var(--ink); color: var(--bone); }
.chip[aria-pressed='true'] b { opacity: 0.7; }

.count {
  margin: 0 0 1.6rem;
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  color: rgb(11 11 10 / 0.55);
  border-top: 1px solid var(--rule);
  padding-top: 0.8rem;
}

.grid {
  display: grid;
  gap: clamp(1.6rem, 3vw, 2.6rem);
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 19rem), 1fr));
}

.gcard { display: grid; align-content: start; gap: 0.9rem; }

/* the dye plate: notation where a photograph does not exist */
.plate {
  position: relative;
  aspect-ratio: 4 / 5;
  display: flex;
  overflow: hidden;
  background: var(--ink);
  transition: transform 380ms var(--ease), box-shadow 380ms var(--ease);
}
.plate span {
  flex: 1;
  transition: flex-grow 420ms var(--ease);
}
.gcard:hover .plate { transform: translateY(-4px); box-shadow: 0 1rem 2.5rem rgb(11 11 10 / 0.16); }
.gcard:hover .plate span:first-child { flex-grow: 2.2; }
.plate-price {
  position: absolute;
  left: 0.7rem;
  bottom: 0.6rem;
  font-family: var(--mono);
  font-size: 0.8rem;
  font-weight: 400;
  letter-spacing: 0.04em;
  color: var(--bone);
  mix-blend-mode: difference;
}

.gcard-body { display: grid; gap: 0.4rem; }
.gcard-name {
  margin: 0.1rem 0 0;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(1.35rem, 2.2vw, 1.75rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
}
.gcard-detail { margin: 0; font-size: 0.95rem; line-height: 1.45; max-width: 36ch; }

/* ---------------------------------------------------------------- the rail */

.rail {
  position: relative;
  z-index: 3;
  background: var(--ink);
  height: 320vh;
}
.rail-stage {
  position: sticky;
  top: 0;
  height: 100svh;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
}
.rail-media { position: relative; overflow: hidden; background: var(--ink); }
.rail-media canvas,
.rail-media img { width: 100%; height: 100%; object-fit: cover; display: block; }
.rail-media::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgb(11 11 10 / 0.5), rgb(11 11 10 / 0.1) 45%, var(--ink));
}
.rail-words {
  position: relative;
  padding: 0 var(--gutter) clamp(1.5rem, 5vh, 3rem);
  display: grid;
  gap: 1.2rem;
  margin-top: -12vh;
}
.facts {
  display: grid;
  gap: 1.2rem 2.4rem;
  margin: 0;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));
}
.fact dt { display: flex; align-items: baseline; gap: 0.6rem; }
.fact dt b {
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(2.6rem, 5vw, 4rem);
  line-height: 0.9;
  color: var(--bone);
}
.fact dt span {
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgb(236 231 220 / 0.6);
}
.fact dd {
  margin: 0.5rem 0 0;
  color: rgb(236 231 220 / 0.82);
  font-size: 0.95rem;
  line-height: 1.5;
  max-width: 34ch;
  border-top: 1px solid var(--rule-bone);
  padding-top: 0.6rem;
}

.rail--still { height: auto; }
.rail--still .rail-stage { position: static; height: auto; }
.rail--still .rail-media { height: 52vh; }

/* ------------------------------------------------------------------ sizing */

.sizing {
  position: relative;
  z-index: 3;
  background: var(--bone);
  color: var(--ink);
  padding: clamp(2.5rem, 8vh, 6rem) var(--gutter);
  display: grid;
  gap: clamp(1.6rem, 4vh, 3rem);
}
.sizing-head { display: grid; gap: 0.6rem; }
.sizing-body {
  display: grid;
  gap: clamp(1.6rem, 4vw, 4rem);
  align-items: start;
}
@media (min-width: 900px) { .sizing-body { grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); } }

.ruler { display: grid; gap: 1.4rem; }
.ruler-pick { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.size--plain { min-width: 3.2rem; }

.bars { list-style: none; margin: 0; padding: 0; display: grid; gap: 1rem; }
.bars li { display: grid; grid-template-columns: 4.5rem minmax(0, 1fr) auto; align-items: center; gap: 0.9rem; }
.bar-label {
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgb(11 11 10 / 0.55);
}
.bar-track { height: 0.55rem; background: rgb(11 11 10 / 0.09); position: relative; }
.bar-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--w);
  background: var(--ink);
  transition: width 460ms var(--ease);
}
.bar-num { font-family: var(--display); font-size: 1.5rem; line-height: 1; }
.bar-num i { font-family: var(--mono); font-size: 0.6rem; font-style: normal; opacity: 0.55; margin-left: 0.2rem; }

.chart { display: grid; gap: 1rem; align-content: start; }
.chart-rows { list-style: none; margin: 0; padding: 0; }
.chart-row {
  display: grid;
  grid-template-columns: 3.5rem repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  padding: 0.62rem 0.5rem;
  font-family: var(--mono);
  font-size: 0.82rem;
  border-bottom: 1px solid var(--rule);
  transition: background 140ms var(--ease);
}
.chart-row--head {
  font-size: 0.62rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgb(11 11 10 / 0.5);
  border-bottom-color: var(--ink);
}
.chart-row.is-pick { background: rgb(11 11 10 / 0.06); }
.advice {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(1.05rem, 1.8vw, 1.35rem);
  line-height: 1.35;
  max-width: 34ch;
}

/* -------------------------------------------------------------------- care */

.care {
  position: relative;
  z-index: 3;
  background: var(--ink);
  color: var(--bone);
  padding: clamp(2.5rem, 8vh, 6rem) var(--gutter);
  display: grid;
  gap: clamp(1.6rem, 4vw, 4rem);
}
@media (min-width: 900px) { .care { grid-template-columns: minmax(0, 22rem) minmax(0, 1fr); align-items: start; } }

.care-plate { margin: 0; display: grid; gap: 0.55rem; }
.care-plate img { width: 100%; aspect-ratio: 1; object-fit: cover; }

.care-body { display: grid; gap: 1.6rem; align-content: start; }
.care-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 1.5rem; }
.care-list li {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 1rem;
  border-top: 1px solid var(--rule-bone);
  padding-top: 1.1rem;
}
.marks { display: flex; gap: 0.4rem; }
.marks i { display: block; }
.marks svg {
  width: 1.9rem;
  height: 1.9rem;
  fill: none;
  stroke: var(--bone);
  stroke-width: 1.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.85;
}
.care-list h3 {
  margin: 0 0 0.35rem;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(1.15rem, 2vw, 1.5rem);
  letter-spacing: -0.015em;
}
.care-list p { margin: 0; color: rgb(236 231 220 / 0.78); max-width: 52ch; line-height: 1.5; }

/* ------------------------------------------------------------------ shipping */

.ship {
  position: relative;
  z-index: 3;
  background: var(--bone-2);
  color: var(--ink);
  padding: clamp(2.5rem, 8vh, 6rem) var(--gutter);
  display: grid;
  gap: clamp(1.4rem, 4vh, 2.6rem);
}
.regions {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0;
}
.regions li {
  display: grid;
  gap: 0.3rem;
  padding: 1.2rem 0;
  border-top: 1px solid var(--rule);
}
.regions li:last-child { border-bottom: 1px solid var(--rule); }
@media (min-width: 760px) {
  .regions li {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr) minmax(0, 1fr);
    align-items: baseline;
    gap: 1.5rem;
  }
}
.regions h3 {
  margin: 0;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(1.3rem, 2.4vw, 1.8rem);
  letter-spacing: -0.02em;
}
.region-cost { margin: 0; font-size: 0.95rem; }
.region-when {
  margin: 0;
  font-family: var(--mono);
  font-size: 0.75rem;
  letter-spacing: 0.06em;
  color: rgb(11 11 10 / 0.7);
  display: grid;
  gap: 0.4rem;
}
.region-bar { display: block; height: 2px; background: rgb(11 11 10 / 0.14); position: relative; }
.region-bar::after {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--w);
  background: var(--clay);
}

.promises { display: grid; gap: 0.8rem; }
.promises p {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(1.1rem, 2vw, 1.5rem);
  line-height: 1.35;
  max-width: 52ch;
}
.promises b { font-weight: 300; color: var(--clay); }

/* ----------------------------------------------------------------- reviews */

.reviews {
  position: relative;
  z-index: 3;
  background: var(--ink);
  color: var(--bone);
  padding: clamp(2.5rem, 8vh, 6rem) var(--gutter);
  display: grid;
  gap: clamp(1.6rem, 4vh, 3rem);
}
.review-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: clamp(1.4rem, 3vw, 2.5rem);
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr));
}
.review-list li { display: grid; gap: 1rem; align-content: start; border-top: 1px solid var(--rule-bone); padding-top: 1.2rem; }
.review-list blockquote {
  margin: 0;
  font-family: var(--display);
  font-weight: 300;
  font-size: clamp(1.05rem, 1.6vw, 1.3rem);
  line-height: 1.4;
  color: var(--bone);
}
.review-who { margin: 0; display: grid; gap: 0.15rem; font-family: var(--mono); font-size: 0.66rem; letter-spacing: 0.1em; }
.review-who b { font-weight: 500; color: var(--bone); }
.review-who span { color: rgb(236 231 220 / 0.55); text-transform: uppercase; }

/* ------------------------------------------------------------------- footer */

.foot {
  background: var(--ink);
  color: var(--bone);
  padding: clamp(2rem, 6vh, 4rem) var(--gutter) clamp(4.5rem, 8vh, 5rem);
  display: grid;
  gap: 0.9rem;
  border-top: 1px solid var(--rule-bone);
}
.wordmark--foot { margin: 0; font-family: var(--display); font-size: clamp(1.6rem, 5vw, 2.6rem); }
.foot .micro { color: rgb(236 231 220 / 0.55); max-width: 60ch; }

/* ---------------------------------------------------------------------- bag */

.bag-tab {
  position: fixed;
  right: clamp(0.9rem, 3vw, 2rem);
  bottom: clamp(0.9rem, 3vw, 2rem);
  z-index: 45;
  min-height: 3.1rem;
  padding: 0.8rem 1.25rem;
  background: var(--clay);
  color: var(--bone);
  border: 1px solid var(--clay);
  font-family: var(--mono);
  font-size: 0.74rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 0.8rem 2rem rgb(11 11 10 / 0.35);
  transition: transform 160ms var(--ease), background 160ms var(--ease);
}
.bag-tab b { font-weight: 500; margin-left: 0.4rem; }
.bag-tab:hover { transform: translateY(-2px); background: #9c5636; }
.bag-tab:active { transform: translateY(0); }

.scrim {
  position: fixed;
  inset: 0;
  z-index: 46;
  border: 0;
  padding: 0;
  background: rgb(11 11 10 / 0.5);
  opacity: 0;
  pointer-events: none;
  transition: opacity 280ms var(--ease);
  cursor: pointer;
}
.scrim.is-open { opacity: 1; pointer-events: auto; }

.bag {
  position: fixed;
  z-index: 47;
  right: 0;
  top: 0;
  bottom: 0;
  width: min(25rem, 100%);
  background: var(--bone);
  color: var(--ink);
  padding: clamp(1.2rem, 3vw, 1.8rem);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  align-content: start;
  gap: 1rem;
  transform: translateX(102%);
  transition: transform 380ms var(--ease);
  overflow-y: auto;
  box-shadow: -1rem 0 3rem rgb(11 11 10 / 0.3);
}
.bag.is-open { transform: none; }

.bag-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; border-bottom: 1px solid var(--rule); padding-bottom: 0.8rem; }
.bag-head h2 { margin: 0; font-family: var(--display); font-weight: 300; font-size: 1.6rem; letter-spacing: -0.02em; }
.x {
  background: transparent;
  border: 1px solid var(--rule);
  color: var(--ink);
  width: 2.5rem;
  height: 2.5rem;
  cursor: pointer;
  transition: background 140ms var(--ease), border-color 140ms var(--ease);
}
.x:hover { background: var(--ink); color: var(--bone); border-color: var(--ink); }

